effect.shader:
precision highp float;

// Calculate the height of the ripple at a given point
float getHeight(vec2 p) {
    float dist = length(p);
    // A decaying sine wave expanding from the center
    float decay = smoothstep(1.0, 0.1, dist);
    return sin(dist * frequency - acTime * speed) * waveAmp * decay;
}

void main() {
    // Normalized pixel coordinates (centered)
    vec2 uv = (acScreenNorm.st - 0.5) * vec2(acScreenSize.x / acScreenSize.y, 1.0);

    // 1. Surface Normals
    // We calculate the slope of the wave to determine how light bounces off it
    float eps = 0.002;
    float h = getHeight(uv);
    float h_x = getHeight(uv + vec2(eps, 0.0));
    float h_y = getHeight(uv + vec2(0.0, eps));

    // Construct normal vector from height gradients
    vec3 normal = normalize(vec3(h - h_x, h - h_y, eps));

    // 2. Lighting Setup
    vec3 viewDir = normalize(vec3(0.0, 0.0, 1.0));
    vec3 col = vec3(0.0); // Start with black background

    // Determine Light Angle based on controls
    float currentAngle = lightAngle;
    if (autoRotate) {
        currentAngle = acTime * 0.3;
    }

    // Light 1
    // Calculate position based on currentAngle
    vec3 lightPos1 = vec3(cos(currentAngle) * lightSpread, sin(currentAngle) * lightSpread, 1.0);
    vec3 lightDir1 = normalize(lightPos1 - vec3(uv, 0.0));
    vec3 halfDir1 = normalize(lightDir1 + viewDir);
    float spec1 = pow(max(dot(normal, halfDir1), 0.0), 80.0); // Sharp highlight

    // Light 2 (Opposite side)
    vec3 lightPos2 = vec3(-lightPos1.x, -lightPos1.y, 1.0);
    vec3 lightDir2 = normalize(lightPos2 - vec3(uv, 0.0));
    vec3 halfDir2 = normalize(lightDir2 + viewDir);
    float spec2 = pow(max(dot(normal, halfDir2), 0.0), 80.0);

    // Combine lights
    col += (spec1 + spec2) * tint.rgb * lightIntensity;

    // 3. Post-Processing
    // Vignette to fade out the edges completely into black
    col *= smoothstep(0.8, 0.2, length(uv));

    // Gamma correction for smoother light falloff
    col = pow(col, vec3(0.4545));

    gl_FragColor = vec4(col, 1.0);
}
